cd /app && cat > app/javascript/controllers/drag_and_drop_controller.js <<'JAVASCRIPT'
import { Controller } from "@hotwired/stimulus"
import { destroy, post } from "@rails/request.js"

export default class extends Controller {
  static classes = [ "draggedItem", "hoverContainer" ]
  static targets = [ "container", "item" ]

  dragStart(event) {
    this.draggedItem = event.target.closest(this.#itemSelector)

    if (this.draggedItem) {
      event.dataTransfer.effectAllowed = "move"
      event.dataTransfer.setData("text/plain", this.draggedItem.id)
      this.draggedItem.classList.add(this.draggedItemClass)
    }
  }

  dragEnter(event) {
    if (this.draggedItem) {
      this.#hover(event.target.closest(this.#containerSelector))
    }
  }

  dragOver(event) {
    if (this.draggedItem) {
      event.preventDefault()
      event.dataTransfer.dropEffect = "move"
    }
  }

  dragLeave(event) {
    if (this.hoveredContainer && !this.hoveredContainer.contains(event.relatedTarget)) {
      this.#clearHoveredContainer()
    }
  }

  drop(event) {
    event.preventDefault()

    const destination = event.target.closest(this.#containerSelector)
    const source = this.draggedItem?.closest(this.#containerSelector)

    if (this.draggedItem && destination && destination !== source) {
      this.#moveCardTo(destination)
      this.#saveCardIn(destination)
    }

    this.#clearDragState()
  }

  dragEnd() {
    this.#clearDragState()
  }

  // Private

  #hover(container) {
    if (container !== this.hoveredContainer) {
      this.#clearHoveredContainer()
      this.hoveredContainer = container
      this.hoveredContainer?.classList.add(this.hoverContainerClass)
    }
  }

  #moveCardTo(container) {
    const list = container.querySelector(".cards__list")
    const cards = [ ...list.querySelectorAll(this.#itemSelector) ].filter(card => card !== this.draggedItem)
    const firstCardAfterGoldenCards = cards.find(card => !card.classList.contains("golden-effect"))

    if (container.dataset.dragAndDropPreservesGoldenness === "true" && !this.draggedItem.classList.contains("golden-effect") && firstCardAfterGoldenCards) {
      firstCardAfterGoldenCards.before(this.draggedItem)
    } else if (cards.length > 0) {
      cards[0].before(this.draggedItem)
    } else {
      list.prepend(this.draggedItem)
    }
  }

  #saveCardIn(container) {
    const status = container.dataset.dragAndDropStatus
    const options = { responseKind: "json" }

    switch (status) {
      case "column":
        post(this.draggedItem.dataset.dragAndDropTriageUrl, {
          ...options,
          body: { column_id: container.dataset.dragAndDropColumnId }
        })
        break
      case "maybe":
        destroy(this.draggedItem.dataset.dragAndDropTriageUrl, options)
        break
      case "not-now":
        post(this.draggedItem.dataset.dragAndDropNotNowUrl, options)
        break
      case "closed":
        post(this.draggedItem.dataset.dragAndDropClosureUrl, options)
        break
    }
  }

  #clearDragState() {
    this.draggedItem?.classList.remove(this.draggedItemClass)
    this.#clearHoveredContainer()
    this.draggedItem = null
  }

  #clearHoveredContainer() {
    this.hoveredContainer?.classList.remove(this.hoverContainerClass)
    this.hoveredContainer = null
  }

  get #containerSelector() {
    return '[data-drag-and-drop-target~="container"]'
  }

  get #itemSelector() {
    return '[data-drag-and-drop-target~="item"]'
  }
}
